 "más básico →": "più basico →",
 "<b>pH 1,5</b><br>Jugo gástrico": "<b>pH 1,5</b><br>Succo gastrico",
 "<b>pH 2,2</b><br>Limón": "<b>pH 2,2</b><br>Limone",
